FROM sys_application
WHERE app_code = #{appCode}

    AND id != #{excludeId}

SELECT id, app_code, app_name, app_desc, status
FROM sys_application
WHERE id = #{id}

mapper.update:
UPDATE sys_application
app_name = #{appName}, status = #{status},
WHERE id = #{id}

mapper.select:
SELECT COUNT(*)
FROM sys_menu
WHERE app_id = #{appId}
  AND menu_code = #{menuCode}

    AND id != #{excludeId}

SELECT id, app_id, parent_id, menu_code, menu_name, menu_type, path, api_revision, status
FROM sys_menu
WHERE id = #{id}

mapper.update:
UPDATE sys_menu
parent_id = #{parentId}, status = #{status}, menu_name = #{menuName},
WHERE id = #{id}

